"""Emit a standalone Python MCP server from endpoint specs."""

from __future__ import annotations

import json
import textwrap
from datetime import datetime, timezone

from . import __version__
from .infer import Endpoint, Param

HEADER = '''\
#!/usr/bin/env python3
"""MCP server for {site}, generated by har2mcp {version} from {source}.

{n} tool(s). Generated {when}. Edit freely: this file is yours now.

Auth values are NOT stored in this file. Set them as environment variables
(or in {env_file} next to this file):
{auth_lines}
Run:  python {filename}        (stdio transport, for Claude Code / Cursor / Codex)
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any

try:  # mcp >= 2
    from mcp.server.mcpserver import MCPServer as _Server
except ImportError:  # mcp 1.x
    from mcp.server.fastmcp import FastMCP as _Server

SERVER_NAME = {site_json}
MAX_CHARS = int(os.environ.get("HAR2MCP_MAX_CHARS", "60000"))
TIMEOUT = float(os.environ.get("HAR2MCP_TIMEOUT", "30"))
_ENV_FILE = Path(__file__).with_name({env_file_json})


def _load_env_file() -> None:
    if not _ENV_FILE.exists():
        return
    for line in _ENV_FILE.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        os.environ.setdefault(key.strip(), value.strip().strip("'\\""))


_load_env_file()
mcp = _Server(SERVER_NAME)


def _auth(fields: list[tuple[str, str, str]]) -> tuple[dict, dict]:
    headers, query = {{}}, {{}}
    for env, wire, where in fields:
        value = os.environ.get(env)
        if value is None:
            continue
        (headers if where == "header" else query)[wire] = value
    return headers, query


def _request(method: str, url: str, query: dict, headers: dict, body: Any, body_kind: str | None,
             auth: list[tuple[str, str, str]]) -> dict:
    auth_headers, auth_query = _auth(auth)
    params = {{k: v for k, v in query.items() if v is not None}}
    params.update(auth_query)
    qs = urllib.parse.urlencode(
        {{k: (json.dumps(v) if isinstance(v, (dict, list)) else str(v).lower() if isinstance(v, bool) else v)
          for k, v in params.items()}}
    )
    full = url + ("?" + qs if qs else "")
    data = None
    hdrs = dict(headers)
    hdrs.update(auth_headers)
    hdrs.setdefault("user-agent", "har2mcp/{version}")
    if body is not None:
        if body_kind == "form" and isinstance(body, dict):
            data = urllib.parse.urlencode(body).encode()
        elif body_kind == "text" and isinstance(body, str):
            data = body.encode()
        else:
            data = json.dumps(body).encode()
            hdrs.setdefault("content-type", "application/json")
    req = urllib.request.Request(full, data=data, headers=hdrs, method=method)
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            status, raw, ctype = resp.status, resp.read(), resp.headers.get("content-type", "")
    except urllib.error.HTTPError as err:
        status, raw, ctype = err.code, err.read(), err.headers.get("content-type", "")
    text = raw.decode("utf-8", "replace")
    result: dict[str, Any] = {{"status": status}}
    try:
        data_out = json.loads(text)
        dumped = json.dumps(data_out)
        if len(dumped) > MAX_CHARS:
            result["truncated"] = True
            result["text"] = dumped[:MAX_CHARS]
        else:
            result["data"] = data_out
    except ValueError:
        result["content_type"] = ctype
        result["text"] = text[:MAX_CHARS]
        if len(text) > MAX_CHARS:
            result["truncated"] = True
    if status in (401, 403):
        result["hint"] = "Auth failed. Re-capture the HAR or refresh the values in " + _ENV_FILE.name
    return result

'''

FOOTER = '''

if __name__ == "__main__":
    mcp.run()
'''


def _annotation(p: Param) -> str:
    base = {"Any": "Any"}.get(p.type, p.type)
    return base if p.required else f"{base} | None"


def _describe(p: Param) -> str:
    bits = [f"{p.where} param `{p.wire}`"]
    if not p.required and p.default is not None:
        bits.append(f"default {json.dumps(p.default)[:80]}")
    ex = [e for e in p.examples if e is not None]
    if ex and p.required:
        bits.append("e.g. " + ", ".join(json.dumps(e)[:40] for e in ex[:3]))
    return "; ".join(bits)


def render_tool(ep: Endpoint) -> str:
    sig = []
    for p in ep.params:
        sig.append(f"{p.name}: {_annotation(p)}" + ("" if p.required else " = None"))
    doc_lines = [
        f"{ep.method} {ep.base}{ep.template}",
        f"Captured {ep.count} time(s). Returns: {ep.response_shape}",
    ]
    if ep.params:
        doc_lines.append("")
        doc_lines.append("Args:")
        doc_lines += [f"    {p.name}: {_describe(p)}" for p in ep.params]
    doc = "\n".join(doc_lines).replace('"""', "'''")

    defaults = {p.name: p.default for p in ep.params if not p.required}
    path_params = [p for p in ep.params if p.where == "path"]
    query_params = [p for p in ep.params if p.where == "query"]
    body_params = [p for p in ep.params if p.where == "body"]
    path_expr = json.dumps(ep.template)
    lines = [f"@mcp.tool()", f"def {ep.tool}({', '.join(sig)}) -> dict:"]
    lines.append(textwrap.indent(f'"""{doc}\n"""', "    "))
    if defaults:
        lines.append(f"    _d = {_py(defaults)}")
    def val(p: Param) -> str:
        return p.name if p.required else f"_d[{p.name!r}] if {p.name} is None else {p.name}"
    if path_params:
        fmt = ", ".join(f"{p.name}=urllib.parse.quote(str({p.name}), safe='')" for p in path_params)
        lines.append(f"    _path = {path_expr}.format({fmt})")
    else:
        lines.append(f"    _path = {path_expr}")
    q_items = [f"{p.wire!r}: {val(p)}" for p in query_params]
    lines.append(f"    _query = {{**{_py(ep.fixed_query)}, " + ", ".join(q_items) + "}" if q_items else f"    _query = {_py(ep.fixed_query)}")
    if ep.body_kind in ("json", "form") and (body_params or ep.fixed_body is not None):
        if isinstance(ep.fixed_body, (list, str, int, float)) and not body_params:
            lines.append(f"    _body = {_py(ep.fixed_body)}")
        else:
            b_items = [f"{p.wire!r}: {val(p)}" for p in body_params]
            lines.append(f"    _body = {{**{_py(ep.fixed_body or {})}, " + ", ".join(b_items) + "}")
    elif ep.raw_body_text is not None:
        lines.append(f"    _body = {ep.raw_body_text!r}")
    else:
        lines.append("    _body = None")
    auth = [(a.env, a.wire, a.where) for a in ep.auth]
    lines.append(
        f"    return _request({ep.method!r}, {json.dumps(ep.base)} + _path, _query, {_py(ep.headers)}, _body, "
        f"{ep.body_kind!r}, {auth!r})"
    )
    return "\n".join(lines)


def _py(obj) -> str:
    """Render JSON-ish data as a Python literal."""
    return repr(json.loads(json.dumps(obj)))


def render_server(endpoints: list[Endpoint], site: str, source: str, filename: str) -> str:
    env_file = f"{site}.env"
    auth_envs = []
    for ep in endpoints:
        for a in ep.auth:
            if a.env not in auth_envs:
                auth_envs.append(a.env)
    auth_lines = "\n".join(f"  {e}" for e in auth_envs) or "  (none detected)"
    head = HEADER.format(
        site=site,
        version=__version__,
        source=source,
        n=len(endpoints),
        when=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
        env_file=env_file,
        auth_lines=auth_lines,
        filename=filename,
        site_json=json.dumps(site),
        env_file_json=json.dumps(env_file),
    )
    return head + "\n\n".join(render_tool(ep) for ep in endpoints) + "\n" + FOOTER


def auth_env_values(endpoints: list[Endpoint], samples) -> dict[str, str]:
    """Pull the captured auth values out of the samples (for --save-secrets)."""
    values: dict[str, str] = {}
    for ep in endpoints:
        for a in ep.auth:
            if a.env in values:
                continue
            for s in samples:
                if a.where == "header" and a.wire in s.headers:
                    values[a.env] = s.headers[a.wire]
                    break
                if a.where == "query":
                    hit = next((v for k, v in s.query if k == a.wire), None)
                    if hit is not None:
                        values[a.env] = hit
                        break
    return values
